{
  "questions": [
    {
      "question_id": "q1",
      "question": "Do you have a reference method that can provide comparison values for API concentration?"
    },
    {
      "question_id": "q2",
      "question": "Do you already have numerical acceptance criteria, such as required accuracy or a detection limit?"
    },
    {
      "question_id": "q3",
      "question": "Over what API concentration range must the measurement track changes?"
    },
    {
      "question_id": "q4",
      "question": "How quickly must an API concentration result be available?"
    },
    {
      "question_id": "q5",
      "question": "Where can the probe be installed at the tablet press feed frame?"
    },
    {
      "question_id": "q6",
      "question": "Is the proposed measurement point hot, under pressure or prone to powder build-up?"
    }
  ],
  "plan": {
    "objective": "Test whether the existing NIR calibration is valid for the new formulation and whether Raman provides additional value.",
    "samples_and_states": [
      {
        "text": "Prepare representative samples of the existing and new formulations spanning the client-agreed API concentration range and relevant powder states.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "reference_measurements": [
      {
        "text": "Obtain independent reference API concentrations for samples matched to the spectral measurements using the agreed reference method.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "setup": [
      {
        "text": "Assess NIR diffuse reflection and Raman separately before testing a combination that measures the same spot at aligned times.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "comparison": [
      {
        "text": "Compare agreement with reference concentrations for the unchanged NIR calibration, formulation-specific single-method models and, only after their assessment, a combined model using dedicated data-fusion processing.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "validation": [
      {
        "text": "Validate on independent new-formulation batches excluded from model development against criteria agreed with the client before testing.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "go_no_go": [
      {
        "text": "Proceed only if independent validation meets the client-agreed criteria for API concentration tracking under the intended process conditions.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "not_demonstrated": [
      {
        "text": "Adding Raman has not been demonstrated here to preserve the existing NIR calibration’s validity for the new formulation.",
        "claim_type": "UNKNOWN",
        "evidence_ids": []
      }
    ],
    "steps": [
      "Agree reference method, acceptance criteria, concentration range and process constraints.",
      "Collect representative existing- and new-formulation samples across agreed variability.",
      "Obtain independent reference API concentrations matched to spectral samples.",
      "Assess methods separately before comparing combined data using dedicated processing.",
      "Validate on independent batches against agreed criteria.",
      "Decide go or no-go from independent comparisons."
    ]
  },
  "decision_basis": [
    {
      "text": "Base the go/no-go decision on comparison with reference concentrations on independent new-formulation material against acceptance criteria agreed with the client before testing.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ]
}
